class RingBuffer {
    private int[] buffer;
    private int head = 0;
    private int tail = 0;
    private int size = 0;
    private int capacity;

    public RingBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new int[capacity];
    }

    // Add an element to the buffer
    public void enqueue(int value) {
        if (size == capacity) {
            System.out.println("Buffer is full. Overwriting oldest element.");
            head = (head + 1) % capacity;  // Move head forward if overwriting
            size--;
        }
        buffer[tail] = value;
        tail = (tail + 1) % capacity;
        size++;
    }

    // Remove and return an element from the buffer
    public int dequeue() {
        if (size == 0) {
            throw new RuntimeException("Buffer is empty!");
        }
        int value = buffer[head];
        head = (head + 1) % capacity;
        size--;
        return value;
    }

    // Check if the buffer is empty
    public boolean isEmpty() {
        return size == 0;
    }

    // Check if the buffer is full
    public boolean isFull() {
        return size == capacity;
    }

    // Print the buffer contents
    public void printBuffer() {
        System.out.print("Buffer: ");
        for (int i = 0; i < size; i++) {
            System.out.print(buffer[(head + i) % capacity] + " ");
        }
        System.out.println();
    }
}

public class Main {
    public static void main(String[] args) {
        RingBuffer rb = new RingBuffer(3);

        rb.enqueue(10);
        rb.enqueue(20);
        rb.enqueue(30);
        rb.printBuffer();  // Output: Buffer: 10 20 30

        rb.enqueue(40);  // Overwrites oldest element (10)
        rb.printBuffer();  // Output: Buffer: 20 30 40

        System.out.println("Dequeued: " + rb.dequeue());  // Output: Dequeued: 20
        rb.printBuffer();  // Output: Buffer: 30 40
    }
}

